/* src/pages/Marketplace.module.css — CargoChain */

.page {
  display: flex;
  flex-direction: column;
  gap: var(--s-4);
  padding-bottom: var(--s-8);
}

/* --- Filter bar --- */
.filterBar {
  padding: var(--s-2);
  border-radius: var(--r-xl);
}

.filterRow {
  display: flex;
  align-items: center;
  gap: var(--s-2);
  flex-wrap: nowrap;
}

.search {
  flex: 1 1 auto;
  min-width: 0;
  max-width: none;
}

.filterRow > .search {
  flex: 1 1 auto;
  min-width: 240px;
  max-width: none;
}

.viewToggle {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  min-height: 40px;
  padding: 4px;
  border-radius: var(--r-lg);
  background: var(--bg-subtle);
  box-shadow: inset 0 0 0 1px var(--border-soft);
  margin-left: auto;
  flex: 0 0 auto;
}

.viewToggleBtn {
  min-height: 44px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 6px 10px;
  border: 0;
  border-radius: var(--r-md);
  background: transparent;
  color: var(--text-secondary);
  font-size: var(--fs-sm);
  font-weight: var(--fw-semibold);
  transition: background var(--dur-1) var(--ease), color var(--dur-1) var(--ease), transform var(--dur-1) var(--ease), box-shadow var(--dur-1) var(--ease);
}

.viewToggleBtn svg {
  width: 16px;
  height: 16px;
}

.viewToggleBtn:hover {
  color: var(--text-primary);
}

.viewToggleBtn:active {
  transform: scale(0.96);
}

.viewToggleActive {
  background: var(--bg-surface);
  color: var(--text-primary);
  box-shadow: var(--shadow-sm);
}

.btnIcon {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
}

/* --- Notice --- */
.notice {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--s-3);
  font-size: var(--fs-sm);
  padding: var(--s-3) var(--s-4);
  background: var(--warning-soft);
  border-color: var(--warning);
  color: var(--text-primary);
}

.muted { color: var(--text-secondary); }

/* --- Table card --- */
.tableCard {
  overflow: hidden;
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--r-lg);
  box-shadow: var(--shadow-sm);
  padding: 0;
}

/* --- Empty card (wraps EmptyState) --- */
.emptyCard {
  display: grid;
  min-height: 280px;
  place-items: center;
  padding: var(--s-2);
}

.loadingState {
  display: grid;
  min-height: 280px;
  place-items: center;
  padding: var(--s-8) var(--s-4);
  color: var(--text-secondary);
  font-size: var(--fs-sm);
}

.skeletonCard {
  pointer-events: none;
}
.skeletonCard:hover { transform: none; box-shadow: var(--shadow-sm); }
.skeletonCard .cardRoute,
.skeletonCard .cardFooter { justify-content: space-between; }

/* --- Route cell (now a clickable button) --- */
.routeCell {
  display: flex;
  align-items: center;
  gap: var(--s-3);
  line-height: 1.2;
  min-width: 0;
  background: transparent;
  border: 0;
  padding: 0;
  font: inherit;
  text-align: left;
  cursor: pointer;
  color: inherit;
  transition: color var(--dur-1) var(--ease), transform var(--dur-1) var(--ease);
}
.routeCell:hover { color: var(--primary); }
.routeCell:active { transform: scale(0.96); }

.pin {
  width: 32px;
  height: 32px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: var(--primary-soft);
  color: var(--primary);
  flex-shrink: 0;
}

.routeText {
  min-width: 0;
  overflow: hidden;
}

.routeFrom {
  font-weight: var(--fw-semibold);
  color: var(--text-primary);
  font-size: var(--fs-md);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.routeCell:hover .routeFrom { color: var(--primary); }

.routeTo {
  font-size: var(--fs-xs);
  color: var(--text-secondary);
  margin-top: 2px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.pendingLabel {
  display: inline-flex;
  align-items: center;
  min-height: 24px;
  width: fit-content;
  padding: 3px 8px;
  border-radius: var(--r-pill);
  background: var(--warning-soft);
  color: var(--warning);
  font-size: var(--fs-xs);
  font-weight: var(--fw-semibold);
  white-space: nowrap;
}

/* --- Reward cell --- */
.rewardCell {
  line-height: 1.2;
  white-space: nowrap;
}

.rewardMain {
  font-weight: var(--fw-semibold);
  color: var(--text-primary);
  font-variant-numeric: tabular-nums;
  font-size: var(--fs-md);
}

/* --- Deadline cell --- */
.deadlineCell {
  display: flex;
  flex-direction: column;
  gap: 2px;
  line-height: 1.2;
  min-width: 0;
}

.deadlineMain {
  font-size: var(--fs-md);
  color: var(--text-primary);
  font-weight: var(--fw-semibold);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.deadlineSub {
  font-size: var(--fs-xs);
  color: var(--text-secondary);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

/* --- Card view --- */
.cardGrid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: var(--s-3);
  padding: var(--s-3);
  background: var(--bg-subtle);
}

.jobCard {
  display: flex;
  flex-direction: column;
  gap: var(--s-3);
  padding: var(--s-4);
  border-radius: var(--r-lg);
  background: var(--bg-surface);
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--border-soft);
  text-align: left;
  width: 100%;
  color: inherit;
  transition: transform var(--dur-2) var(--ease), box-shadow var(--dur-2) var(--ease), background var(--dur-1) var(--ease);
}

.jobCard:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
  background: rgba(37, 99, 235, 0.01);
}

.jobCard:active {
  transform: scale(0.98);
}

.cardTop {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--s-3);
  width: 100%;
}

.cardId {
  color: var(--primary);
  font-family: var(--font-mono);
  font-size: var(--fs-xs);
  font-weight: var(--fw-bold);
  font-variant-numeric: tabular-nums;
  background: var(--primary-soft);
  padding: 2px 6px;
  border-radius: var(--r-sm);
}

.cardTime {
  color: var(--text-muted);
  font-size: var(--fs-xs);
}

.cardRoute {
  display: flex;
  align-items: center;
  gap: var(--s-2);
  width: 100%;
  margin-top: var(--s-1);
}

.routeFrom,
.routeTo {
  font-size: var(--fs-sm);
  font-weight: var(--fw-bold);
  color: var(--text-primary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 120px;
}

.routeArrow {
  color: var(--primary);
  font-weight: var(--fw-bold);
  font-size: var(--fs-xs);
  flex-shrink: 0;
}

.cardCargo {
  display: flex;
  align-items: center;
  gap: var(--s-2);
  padding: var(--s-2) var(--s-3);
  border-radius: var(--r-sm);
  background: var(--bg-subtle);
  font-size: var(--fs-xs);
  width: 100%;
  box-shadow: inset 0 0 0 1px var(--border-soft);
  margin-top: var(--s-1);
}

.cargoIcon {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
}

.cargoText {
  color: var(--text-secondary);
  font-weight: var(--fw-medium);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  min-width: 0;
}

.specialBadge {
  display: flex;
  align-items: center;
  gap: var(--s-2);
  padding: var(--s-2) var(--s-3);
  border-radius: var(--r-sm);
  background: var(--warning-soft);
  border-left: 3px solid var(--warning);
  font-size: var(--fs-xs);
  color: var(--warning);
  font-weight: var(--fw-semibold);
  width: 100%;
  box-shadow: var(--shadow-sm);
  margin-top: var(--s-1);
}

.warningIcon {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
}

.specialText {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  min-width: 0;
}

.specialLabel {
  flex: 0 0 auto;
  color: var(--warning);
  font-size: var(--fs-xs);
  font-weight: var(--fw-semibold);
}

.cardDivider {
  height: 1px;
  background: var(--border-soft);
  width: 100%;
  margin: var(--s-1) 0;
}

.cardFooter {
  display: flex;
  justify-content: space-between;
  align-items: center;
  width: 100%;
  gap: var(--s-3);
}

.cardOpenButton {
  display: inline-flex;
  min-height: 44px;
  align-items: center;
  align-self: flex-start;
  gap: 6px;
  margin-top: var(--s-1);
  padding: 0 2px;
  border: 0;
  color: var(--primary);
  background: transparent;
  font: inherit;
  font-size: var(--fs-sm);
  font-weight: var(--fw-semibold);
  cursor: pointer;
  transition-property: color, transform;
  transition-duration: var(--dur-1);
  transition-timing-function: var(--ease);
}

.cardOpenButton:hover { color: var(--primary-hover); text-decoration: underline; }
.cardOpenButton:active { transform: scale(0.96); }
.cardOpenButton svg { width: 16px; height: 16px; }

.cardPaymentBox,
.cardDeadlineBox {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.footerLabel {
  font-size: var(--fs-xs);
  font-weight: var(--fw-bold);
  color: var(--text-secondary);
  letter-spacing: 0.05em;
}

.footerVal {
  font-size: var(--fs-sm);
  color: var(--text-primary);
  font-weight: var(--fw-bold);
  font-variant-numeric: tabular-nums;
}

/* --- Simplified Table specific layout --- */
.tableRouteRow {
  display: flex;
  align-items: center;
  gap: var(--s-3);
  font-weight: var(--fw-semibold);
  color: var(--text-primary);
  font-size: var(--fs-base);
  min-width: 0;
}

.tableRouteLabel {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 140px;
  min-width: 0;
}

.tableRouteArrow {
  color: var(--primary);
  font-weight: var(--fw-bold);
  font-size: var(--fs-md);
  flex-shrink: 0;
}

.tableCargoLabel {
  font-size: var(--fs-sm);
  color: var(--text-secondary);
  font-weight: var(--fw-medium);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 200px;
  display: inline-block;
  min-width: 0;
}

.tableId {
  font-family: var(--font-mono);
  font-weight: var(--fw-bold);
  color: var(--text-primary);
  font-size: var(--fs-sm);
  font-variant-numeric: tabular-nums;
}

.rewardSub {
  font-size: var(--fs-xs);
  color: var(--text-secondary);
  margin-top: 2px;
  font-variant-numeric: tabular-nums;
  font-weight: var(--fw-medium);
}

.rowAction {
  display: inline-flex;
  width: 40px;
  min-width: 40px;
  height: 40px;
  min-height: 40px;
  align-items: center;
  justify-content: center;
  padding: 0;
  border: 1px solid transparent;
  border-radius: var(--r-md);
  background: transparent;
  color: var(--primary);
  cursor: pointer;
  transition-property: background-color, border-color, color, transform;
  transition-duration: var(--dur-1);
  transition-timing-function: var(--ease);
}
.rowAction:hover {
  background: var(--primary-soft);
  border-color: color-mix(in srgb, var(--primary) 18%, var(--border-soft));
}
.rowAction:focus-visible { outline: 2px solid var(--primary); outline-offset: 2px; }
.rowAction:active { transform: scale(0.96); }
.rowAction svg { width: 18px; height: 18px; }

/* --- Empty state inside table --- */
.empty {
  text-align: center;
  padding: var(--s-8) var(--s-4);
  color: var(--text-muted);
  font-style: italic;
}

@media (max-width: 640px) {
  .filterRow {
    align-items: stretch;
    flex-wrap: wrap;
  }

  .filterRow > .search {
    flex: 1 1 100%;
    min-width: 0;
  }

  .viewToggle {
    margin-left: auto;
  }

  .viewToggleBtn {
    flex: 1;
  }

  .cardGrid {
    grid-template-columns: 1fr;
  }

  .cardFacts {
    grid-template-columns: 1fr;
  }
}
