.page {
  display: flex;
  flex-direction: column;
  gap: var(--s-4);
  padding-bottom: var(--s-8);
}

.contentToolbar {
  display: flex;
  justify-content: flex-start;
  min-height: 40px;
}

.backIcon {
  width: 16px;
  height: 16px;
}

.muted {
  display: block;
  color: var(--text-secondary);
  font-size: var(--fs-xs);
}

.walletIdentity {
  display: block;
  max-width: 100%;
  overflow-wrap: anywhere;
  font-family: var(--font-sans);
  font-size: var(--fs-sm);
  font-weight: var(--fw-bold);
  line-height: 1.45;
}

.header {
  display: flex;
  flex-direction: column;
  gap: var(--s-4);
}

.headerTop,
.routeBlock,
.footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--s-4);
}

.party {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 2px;
  font-family: var(--font-mono);
  font-size: var(--fs-sm);
}

.label {
  display: block;
  margin-bottom: 3px;
  color: var(--text-secondary);
  font-family: var(--font-sans);
  font-size: var(--fs-xs);
  font-weight: var(--fw-semibold);
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.routeBlock {
  justify-content: flex-start;
  padding: var(--s-4);
  border-radius: var(--r-md);
  background: var(--bg-subtle);
  box-shadow: inset 0 0 0 1px var(--border-soft);
}

.routeIcon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  flex-shrink: 0;
  border-radius: 50%;
  background: var(--primary-soft);
  color: var(--primary);
}

.routeIcon svg {
  width: 20px;
  height: 20px;
}

.route {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--s-2);
  min-width: 0;
  color: var(--text-primary);
  font-size: var(--fs-md);
}

.route > span {
  color: var(--text-muted);
}

.payment {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  margin-left: auto;
  font-size: var(--fs-lg);
  font-variant-numeric: tabular-nums;
}

.factGrid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--s-4);
}

.fact {
  display: flex;
  align-items: flex-start;
  gap: var(--s-3);
}

.fact strong {
  display: block;
  color: var(--text-primary);
  font-size: var(--fs-md);
  font-variant-numeric: tabular-nums;
}

.factIcon,
.sectionIcon {
  width: 22px;
  height: 22px;
  flex-shrink: 0;
  color: var(--primary);
}

.manifest {
  overflow: hidden;
}

.sectionHeader {
  display: flex;
  align-items: flex-start;
  gap: var(--s-3);
  padding: var(--s-4) var(--s-5);
  border-bottom: 1px solid var(--border-soft);
}

.sectionHeader h2 {
  margin: 0;
  color: var(--text-primary);
  font-size: var(--fs-md);
  text-wrap: balance;
}

.sectionHeader p {
  margin: 2px 0 0;
  color: var(--text-secondary);
  font-size: var(--fs-xs);
}

.itemList {
  display: flex;
  flex-direction: column;
}

.itemRow {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--s-4);
  padding: var(--s-3) var(--s-5);
  border-bottom: 1px solid var(--border-soft);
}

.itemRow:last-child {
  border-bottom: 0;
}

.itemRow strong {
  color: var(--text-primary);
  font-size: var(--fs-sm);
}

.itemRow p {
  margin: 3px 0 0;
  color: var(--text-secondary);
  font-size: var(--fs-sm);
  line-height: 1.5;
  text-wrap: pretty;
}

.quantity {
  flex-shrink: 0;
  color: var(--text-secondary);
  font-size: var(--fs-xs);
  font-weight: var(--fw-semibold);
  font-variant-numeric: tabular-nums;
}

.instructions {
  display: grid;
  grid-template-columns: 40px minmax(0, 1fr);
  align-items: start;
  gap: var(--s-3);
  margin: var(--s-4) var(--s-5) var(--s-5);
  padding: var(--s-2);
  border-radius: var(--r-xl);
  background: linear-gradient(135deg, color-mix(in srgb, var(--primary-soft) 82%, var(--bg-surface)), var(--bg-surface));
  box-shadow: var(--shadow-border), var(--shadow-md);
}

.instructionsIcon {
  width: 40px;
  height: 40px;
  display: grid;
  place-items: center;
  border-radius: var(--r-md);
  color: var(--primary);
  background: var(--bg-surface);
  box-shadow: var(--shadow-sm);
}

.instructionsIcon svg {
  width: 20px;
  height: 20px;
}

.instructionsBody {
  display: grid;
  gap: 2px;
  min-width: 0;
  padding: var(--s-1) 0;
}

.instructionsLabel {
  color: var(--primary-text);
  font-size: var(--fs-xs);
  font-weight: var(--fw-bold);
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.instructions p {
  margin: 0;
  color: var(--text-primary);
  font-size: var(--fs-sm);
  line-height: var(--lh-normal);
  overflow-wrap: anywhere;
  text-wrap: pretty;
}

.footer {
  justify-content: flex-end;
  flex-wrap: wrap;
  padding-top: var(--s-2);
}

.proposalCount {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 18px;
  height: 18px;
  padding: 0 5px;
  border-radius: var(--r-pill);
  background: rgba(255, 255, 255, 0.2);
  color: inherit;
  font-size: var(--fs-xs);
  font-variant-numeric: tabular-nums;
  line-height: 1;
}

.dashboardGrid {
  display: grid;
  grid-template-columns: minmax(0, 1.55fr) minmax(280px, 0.85fr);
  gap: var(--s-4);
  align-items: start;
}

.leftColumn,
.rightColumn {
  display: flex;
  flex-direction: column;
  gap: var(--s-4);
  min-width: 0;
}

.sectionCard {
  overflow: hidden;
}

.routeTimeline {
  padding: var(--s-5);
}

.routeStop {
  display: grid;
  grid-template-columns: 36px minmax(0, 1fr);
  align-items: center;
  gap: var(--s-3);
}

.routeStop strong {
  display: block;
  color: var(--text-primary);
  font-size: var(--fs-md);
  text-wrap: balance;
}

.routeDot {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: var(--primary);
  color: #fff;
  font-size: var(--fs-xs);
  font-weight: var(--fw-bold);
  box-shadow: 0 0 0 4px var(--primary-soft);
}

.routeDotEnd {
  background: var(--success);
  box-shadow: 0 0 0 4px var(--success-soft);
}

.routeLine {
  display: block;
  width: 2px;
  height: 30px;
  margin-left: 15px;
  background: var(--border);
}

.escrowCard {
  display: flex;
  flex-direction: column;
  gap: var(--s-1);
  background: var(--bg-subtle);
}

.escrowValue {
  color: var(--text-primary);
  font-size: var(--fs-2xl);
  font-variant-numeric: tabular-nums;
  line-height: var(--lh-tight);
}

.metaCard {
  padding-top: var(--s-2);
  padding-bottom: var(--s-2);
}

.metaRow {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--s-3);
  min-height: 56px;
  border-bottom: 1px solid var(--border-soft);
}

.metaRow:last-child {
  border-bottom: 0;
}

.metaRow > .label {
  margin: 0;
}

.metaRow > strong {
  color: var(--text-primary);
  font-family: var(--font-mono);
  font-size: var(--fs-sm);
  font-weight: var(--fw-semibold);
  text-align: right;
}

.metaRow > strong span {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
}

.metaRow small {
  margin-top: 2px;
  color: var(--text-secondary);
  font-family: var(--font-sans);
  font-size: var(--fs-xs);
  font-weight: var(--fw-normal);
}

/* Keep the carrier's primary action in the desktop summary rail. The footer
   copy remains the mobile fallback so the narrow layout keeps its existing
   action order. */
.summaryAction {
  display: none;
  gap: var(--s-2);
  padding: var(--s-4);
  border-radius: var(--r-lg);
  background: linear-gradient(135deg, color-mix(in srgb, var(--primary-soft) 82%, var(--bg-surface)), var(--bg-surface));
  box-shadow: var(--shadow-border), var(--shadow-sm);
}

.summaryActionKicker {
  color: var(--primary-text);
  font-size: var(--fs-xs);
  font-weight: var(--fw-bold);
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.summaryAction strong {
  color: var(--text-primary);
  font-size: var(--fs-md);
  text-wrap: balance;
}

.summaryAction p {
  margin: 0;
  color: var(--text-secondary);
  font-size: var(--fs-sm);
  line-height: var(--lh-normal);
  text-wrap: pretty;
}

.summaryAction :global(button) { width: 100%; margin-top: var(--s-1); }

@media (min-width: 768px) {
  .summaryAction { display: grid; }
  .footerProposalAction { display: none; }
}

@media (max-width: 700px) {
  .dashboardGrid {
    grid-template-columns: 1fr;
  }

  .factGrid {
    grid-template-columns: 1fr;
  }

  .routeBlock {
    align-items: flex-start;
    flex-wrap: wrap;
  }

  .payment {
    width: 100%;
    align-items: flex-start;
    margin-left: 60px;
  }
}
